import { useCallback, useState } from 'react';
import ApiService from '../services/api';
import type { MitigationAction, SelectedMitigationAction } from '../types/mitigation';
import { findRecommendationIndex, mergeSelectedActions } from '../utils/mitigationActions';

export interface MitigationRecommendationRow {
  id: string;
  title: string;
  category?: string;
  mitigationActions?: MitigationAction[];
  selectedActions?: SelectedMitigationAction[];
  isImplemented?: boolean;
  status?: string;
}

interface UseMitigationActionSelectionOptions {
  assessmentId: string | null;
  recommendations: MitigationRecommendationRow[];
  onRecommendationsChange: (next: MitigationRecommendationRow[]) => void;
  onError?: (message: string | null) => void;
}

export function useMitigationActionSelection({
  assessmentId,
  recommendations,
  onRecommendationsChange,
  onError,
}: UseMitigationActionSelectionOptions) {
  const [savingActionKey, setSavingActionKey] = useState<string | null>(null);

  const handleToggleMitigationAction = useCallback(
    async (rec: MitigationRecommendationRow, action: MitigationAction, selected: boolean) => {
      if (!assessmentId) {
        onError?.('Run a carbon assessment first so mitigation measures can be tracked.');
        return;
      }

      const recommendationIndex = findRecommendationIndex(recommendations, rec);
      if (recommendationIndex < 0) {
        onError?.('This recommendation is not linked to your latest assessment yet.');
        return;
      }

      const actionKey = `${rec.id}::${action.id}`;
      setSavingActionKey(actionKey);
      onError?.(null);

      const optimisticSelected = mergeSelectedActions(
        recommendations[recommendationIndex]?.selectedActions || rec.selectedActions || [],
        action,
        selected
      );

      const optimistic = recommendations.map((item, index) =>
        index === recommendationIndex ? { ...item, selectedActions: optimisticSelected } : item
      );
      onRecommendationsChange(optimistic);

      try {
        await ApiService.selectMitigationAction({
          assessmentId,
          recommendationIndex,
          actionId: action.id,
          action: {
            label: action.label,
            implementationTrack: action.implementationTrack,
            estimatedImpactKg: action.estimatedImpactKg,
          },
          selected,
        });
      } catch (error) {
        console.error('Select mitigation action:', error);
        onError?.('Could not save your measure selection. Try again in a moment.');
        const reverted = recommendations.map((item, index) =>
          index === recommendationIndex
            ? {
                ...item,
                selectedActions: mergeSelectedActions(
                  item.selectedActions || [],
                  action,
                  !selected
                ),
              }
            : item
        );
        onRecommendationsChange(reverted);
      } finally {
        setSavingActionKey(null);
      }
    },
    [assessmentId, onError, onRecommendationsChange, recommendations]
  );

  return {
    savingActionKey,
    handleToggleMitigationAction,
    canSelectActions: Boolean(assessmentId),
  };
}
